class User {
  constructor(
    id,
    entity,
    entity_title,
    names,
    first_name,
    last_name,
    gender,
    national_id,
    email,
    phone,
    date_of_birth,
    country,
    country_title,
    county,
    county_title,
    image,
    status
  ) {
    this.id = id;
    this.entity = entity;
    this.entity_title = entity_title;
    this.names = names;
    this.first_name = first_name;
    this.last_name = last_name;
    this.gender = gender;
    this.national_id = national_id;
    this.email = email;
    this.phone = phone;
    this.date_of_birth = date_of_birth;
    this.country = country;
    this.country_title = country_title;
    this.county = county;
    this.county_title = county_title;
    this.image = image;
    this.status = status;
  }
}

export default User;
